WITH src AS (SELECT * FROM accounts WHERE balance >= 51000 AND account_type IN ('LOAN', 'CREDIT', 'SAVINGS') AND opened_date BETWEEN '2025-07-01' AND '2025-10-01'), accounts_stats AS (SELECT CASE WHEN status IN ('FROZEN', 'CLOSED') THEN 'group_a' ELSE 'other' END AS status_group, COUNT(balance) AS balance_count, MAX(opened_date) AS last_opened_date FROM src GROUP BY CASE WHEN status IN ('FROZEN', 'CLOSED') THEN 'group_a' ELSE 'other' END) SELECT status_group, balance_count FROM accounts_stats WHERE balance_count < 8 ORDER BY balance_count DESC, status_group LIMIT 5;
